#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <torch/extension.h>

#include "kernel.h"

// Destination-passing-style entry point matching the
// reference shape contract at
// references/NVIDIA_Manuals/solbench_problems/problem_012_gqa_paged_decode_h32_kv4_d128_ps1.md.
//
//   q          [B, H_q=32, D=128]  bf16
//   k_cache    [num_pages, page_size=1, H_kv=4, D=128]  bf16
//   v_cache    same shape as k_cache
//   kv_indptr  [B+1]  int32
//   kv_indices [N]    int32
//   sm_scale   scalar float32
//   output     [B, H_q, D]  bf16   (in-place)
//   lse        [B, H_q]     fp32   (in-place; base-2 log-sum-exp)
void run(
    torch::Tensor q,
    torch::Tensor k_cache,
    torch::Tensor v_cache,
    torch::Tensor kv_indptr,
    torch::Tensor kv_indices,
    double sm_scale,
    torch::Tensor output,
    torch::Tensor lse) {

    TORCH_CHECK(q.is_cuda(), "q must be CUDA");
    TORCH_CHECK(k_cache.is_cuda(), "k_cache must be CUDA");
    TORCH_CHECK(v_cache.is_cuda(), "v_cache must be CUDA");
    TORCH_CHECK(kv_indptr.is_cuda(), "kv_indptr must be CUDA");
    TORCH_CHECK(kv_indices.is_cuda(), "kv_indices must be CUDA");
    TORCH_CHECK(output.is_cuda(), "output must be CUDA");
    TORCH_CHECK(lse.is_cuda(), "lse must be CUDA");

    TORCH_CHECK(q.dtype() == torch::kBFloat16, "q must be bf16");
    TORCH_CHECK(k_cache.dtype() == torch::kBFloat16, "k_cache must be bf16");
    TORCH_CHECK(v_cache.dtype() == torch::kBFloat16, "v_cache must be bf16");
    TORCH_CHECK(kv_indptr.dtype() == torch::kInt32, "kv_indptr must be int32");
    TORCH_CHECK(kv_indices.dtype() == torch::kInt32, "kv_indices must be int32");
    TORCH_CHECK(output.dtype() == torch::kBFloat16, "output must be bf16");
    TORCH_CHECK(lse.dtype() == torch::kFloat32, "lse must be fp32");

    TORCH_CHECK(q.is_contiguous(), "q must be contiguous");
    TORCH_CHECK(k_cache.is_contiguous(), "k_cache must be contiguous");
    TORCH_CHECK(v_cache.is_contiguous(), "v_cache must be contiguous");
    TORCH_CHECK(kv_indptr.is_contiguous(), "kv_indptr must be contiguous");
    TORCH_CHECK(kv_indices.is_contiguous(), "kv_indices must be contiguous");
    TORCH_CHECK(output.is_contiguous(), "output must be contiguous");
    TORCH_CHECK(lse.is_contiguous(), "lse must be contiguous");

    TORCH_CHECK(q.dim() == 3, "q must be 3D");
    TORCH_CHECK(k_cache.dim() == 4, "k_cache must be 4D");
    TORCH_CHECK(v_cache.dim() == 4, "v_cache must be 4D");
    TORCH_CHECK(kv_indptr.dim() == 1, "kv_indptr must be 1D");
    TORCH_CHECK(kv_indices.dim() == 1, "kv_indices must be 1D");
    TORCH_CHECK(output.dim() == 3, "output must be 3D");
    TORCH_CHECK(lse.dim() == 2, "lse must be 2D");

    const int64_t B = q.size(0);
    const int64_t H_q = q.size(1);
    const int64_t D = q.size(2);
    TORCH_CHECK(H_q == 32, "num_qo_heads must equal 32");
    TORCH_CHECK(D == 128, "head_dim must equal 128");

    TORCH_CHECK(k_cache.size(1) == 1, "page_size must equal 1");
    const int64_t H_kv = k_cache.size(2);
    TORCH_CHECK(H_kv == 4, "num_kv_heads must equal 4");
    TORCH_CHECK(k_cache.size(3) == D, "k_cache head_dim mismatch");
    TORCH_CHECK(v_cache.size(0) == k_cache.size(0)
                && v_cache.size(1) == 1
                && v_cache.size(2) == H_kv
                && v_cache.size(3) == D,
                "v_cache shape mismatch with k_cache");

    TORCH_CHECK(kv_indptr.size(0) == B + 1,
                "kv_indptr length must equal batch_size + 1");
    TORCH_CHECK(output.size(0) == B && output.size(1) == H_q
                && output.size(2) == D,
                "output shape mismatch");
    TORCH_CHECK(lse.size(0) == B && lse.size(1) == H_q,
                "lse shape mismatch");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_012_gqa_paged_decode_launcher(
        q, k_cache, v_cache, kv_indptr, kv_indices,
        static_cast<float>(sm_scale),
        output, lse, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "GQA paged decode (problem_012); destination-passing-style; "
        "online softmax; FP32 accumulators with BF16 inputs/outputs.");
}

// GQA paged decode kernel: matches the Python reference
// at references/NVIDIA_Manuals/solbench_problems/problem_012_gqa_paged_decode_h32_kv4_d128_ps1.md.
//
// Parallelization: one block per (batch, query_head)
// pair; 128 threads per block (one per head_dim
// element). Online softmax (Flash-Attention style)
// keeps the per-block memory small.
//
// Precision: FP32 accumulators throughout; BF16 inputs
// read into float; BF16 cast at the output write.

#include <ATen/cuda/CUDAContext.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>
#include <torch/extension.h>

#include "kernel.h"

namespace {

constexpr int HEAD_DIM = 128;
constexpr int NUM_QO_HEADS = 32;
constexpr int NUM_KV_HEADS = 4;
constexpr int GQA_RATIO = NUM_QO_HEADS / NUM_KV_HEADS;  // 8

// Block-wide reduction across 128 threads = 4 warps. The
// warp shuffle reduces within each warp; the per-warp
// partials are written to shared memory and reduced by
// warp 0.
__device__ __forceinline__ float block_sum_128(
    float v, float* sdata_4) {
    // Intra-warp reduction.
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, offset);
    }
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) sdata_4[warp] = v;
    __syncthreads();
    float r = 0.0f;
    if (warp == 0) {
        float w = (lane < 4) ? sdata_4[lane] : 0.0f;
        for (int offset = 2; offset > 0; offset >>= 1) {
            w += __shfl_xor_sync(0xffffffff, w, offset);
        }
        if (lane == 0) sdata_4[0] = w;
    }
    __syncthreads();
    return sdata_4[0];
}

__global__ void gqa_paged_decode_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k_cache,
    const __nv_bfloat16* __restrict__ v_cache,
    const int* __restrict__ kv_indptr,
    const int* __restrict__ kv_indices,
    float sm_scale,
    __nv_bfloat16* __restrict__ output,
    float* __restrict__ lse,
    int batch_size) {

    const int b = blockIdx.x;
    const int h = blockIdx.y;
    const int tid = threadIdx.x;
    if (b >= batch_size || h >= NUM_QO_HEADS) return;

    const int kv_head = h / GQA_RATIO;

    const int page_start = kv_indptr[b];
    const int page_end = kv_indptr[b + 1];
    const int num_tokens = page_end - page_start;

    const int output_offset = (b * NUM_QO_HEADS + h) * HEAD_DIM;

    if (num_tokens <= 0) {
        if (tid < HEAD_DIM) {
            output[output_offset + tid] = __float2bfloat16(0.0f);
        }
        if (tid == 0) {
            lse[b * NUM_QO_HEADS + h] = -INFINITY;
        }
        return;
    }

    // Load q[b, h, tid] once into a register.
    const float q_val = (tid < HEAD_DIM)
        ? __bfloat162float(q[output_offset + tid])
        : 0.0f;

    // Shared scratch:
    //   sdata_dot[0..3] -- 4-warp reduction buffer for dot products
    //   m_smem        -- running max
    //   l_smem        -- running sum_exp
    //   logit_smem    -- per-token logit (broadcast to all threads)
    //   rescale_smem  -- old-softmax rescale, published by thread 0
    //   exp_logit_smem -- new-token weight, published by thread 0
    __shared__ float sdata_dot[4];
    __shared__ float m_smem;
    __shared__ float l_smem;
    __shared__ float logit_smem;
    __shared__ float rescale_smem;
    __shared__ float exp_logit_smem;

    if (tid == 0) {
        m_smem = -INFINITY;
        l_smem = 0.0f;
    }
    __syncthreads();

    float acc = 0.0f;

    for (int i = 0; i < num_tokens; ++i) {
        const int token_idx = kv_indices[page_start + i];
        const int kv_offset = (token_idx * NUM_KV_HEADS + kv_head) * HEAD_DIM + tid;
        const float k_val = (tid < HEAD_DIM)
            ? __bfloat162float(k_cache[kv_offset]) : 0.0f;
        const float v_val = (tid < HEAD_DIM)
            ? __bfloat162float(v_cache[kv_offset]) : 0.0f;

        const float prod = q_val * k_val;
        const float dot = block_sum_128(prod, sdata_dot);

        if (tid == 0) {
            logit_smem = dot * sm_scale;
        }
        __syncthreads();
        const float logit = logit_smem;

        // Thread 0 owns the running softmax state and publishes both factors
        // before any output lane consumes them.  Letting every warp read
        // m_smem while thread 0 overwrites it is a read/write race: later
        // warps can observe m_new as m_prev and skip the required rescale.
        if (tid == 0) {
            const float m_prev = m_smem;
            const float m_new = fmaxf(m_prev, logit);
            rescale_smem = (m_prev == -INFINITY) ? 0.0f
                : expf(m_prev - m_new);
            exp_logit_smem = expf(logit - m_new);
            l_smem = l_smem * rescale_smem + exp_logit_smem;
            m_smem = m_new;
        }
        __syncthreads();

        acc = acc * rescale_smem + exp_logit_smem * v_val;
    }

    const float m_final = m_smem;
    const float l_final = l_smem;

    if (tid < HEAD_DIM) {
        const float out_val = acc / l_final;
        output[output_offset + tid] = __float2bfloat16(out_val);
    }
    if (tid == 0) {
        const float lse_val = (m_final + logf(l_final)) * (1.0f / 0.69314718055994530942f);
        // (1/log(2)) = log2(e); m + log(l) is natural log-sum-exp.
        lse[b * NUM_QO_HEADS + h] = lse_val;
    }
}

}  // namespace

void problem_012_gqa_paged_decode_launcher(
    const torch::Tensor& q,
    const torch::Tensor& k_cache,
    const torch::Tensor& v_cache,
    const torch::Tensor& kv_indptr,
    const torch::Tensor& kv_indices,
    float sm_scale,
    torch::Tensor output,
    torch::Tensor lse,
    cudaStream_t stream) {

    const int batch_size = static_cast<int>(q.size(0));

    dim3 grid(batch_size, NUM_QO_HEADS, 1);
    dim3 block(128, 1, 1);

    gqa_paged_decode_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(k_cache.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(v_cache.data_ptr<at::BFloat16>()),
        kv_indptr.data_ptr<int>(),
        kv_indices.data_ptr<int>(),
        sm_scale,
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        lse.data_ptr<float>(),
        batch_size);
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// GQA paged decode kernel launcher. One block per
// (batch, query head); 128 threads per block.
//
//   q          : [B, H_q=32, D=128]  bf16
//   k_cache    : [num_pages, page_size=1, H_kv=4, D=128]  bf16
//   v_cache    : same shape as k_cache
//   kv_indptr  : [B+1] int32 (per-batch token range start/end)
//   kv_indices : [N] int32 (token indices into k_cache / v_cache)
//   sm_scale   : float
//   output     : [B, H_q, D] bf16 (in-place)
//   lse        : [B, H_q] float32 (in-place); base-2 log-sum-exp
//
// Algorithm:
//   per (b, h):
//     kv_head = h / gqa_ratio  (gqa_ratio = H_q / H_kv = 8)
//     for token i in kv_indices[kv_indptr[b] : kv_indptr[b+1]]:
//       logit_i = (q[b, h] @ k_cache[i, kv_head]) * sm_scale
//     attn = softmax(logits)
//     output[b, h] = attn @ v_cache[token, kv_head]
//     lse[b, h]    = log2(sum(exp(logits)))
//
// Empty-token batches (kv_indptr[b] == kv_indptr[b+1])
// produce zero output and lse = -inf (matches the
// reference's `output[b].zero_()` + initial-lse fill).
void problem_012_gqa_paged_decode_launcher(
    const torch::Tensor& q,
    const torch::Tensor& k_cache,
    const torch::Tensor& v_cache,
    const torch::Tensor& kv_indptr,
    const torch::Tensor& kv_indices,
    float sm_scale,
    torch::Tensor output,
    torch::Tensor lse,
    cudaStream_t stream);
